package com.bank.azurelb.l4;

import java.util.List;
import java.util.logging.Logger;

// Azure Load Balancer (L4): balance by 5-tuple hash, no HTTP awareness.
public class AzureLoadBalancerL4 {
    private static final Logger log = Logger.getLogger(AzureLoadBalancerL4.class.getName());

    // backends are healthy node/pod endpoints; pick by hash of the connection tuple.
    public String route(List<String> healthyBackends, String srcIp, int srcPort) {
        if (healthyBackends.isEmpty()) throw new IllegalStateException("no healthy backends");
        int hash = Math.abs((srcIp + ":" + srcPort).hashCode());
        String backend = healthyBackends.get(hash % healthyBackends.size());
        log.fine(() -> "L4 LB " + srcIp + ":" + srcPort + " -> " + backend + " (5-tuple hash)");
        return backend;
    }
}
