package com.bank.azurelb.regional;

import com.bank.azurelb.l4.AzureLoadBalancerL4;
import java.util.List;
import java.util.logging.Logger;

// Application Gateway (L7): path-based routing + WAF + TLS termination.
public class ApplicationGatewayL7 {
    private static final Logger log = Logger.getLogger(ApplicationGatewayL7.class.getName());
    private final AzureLoadBalancerL4 dataPlane = new AzureLoadBalancerL4();

    // Simple WAF: block obvious injection patterns before they reach backends.
    public boolean wafBlocks(String payload) {
        String p = payload == null ? "" : payload.toLowerCase();
        boolean malicious = p.contains("' or '1'='1") || p.contains("<script>") || p.contains("drop table");
        if (malicious) log.severe(() -> "WAF BLOCK malicious request: " + payload);
        return malicious;
    }

    // Route by URL path to the correct backend pool, then L4-balance within it.
    public String route(String path, String payload, String srcIp, int srcPort,
                        List<String> transferPool, List<String> loanPool) {
        if (wafBlocks(payload)) return "403-WAF";
        List<String> pool = path.startsWith("/api/v1/transfers") ? transferPool
                : path.startsWith("/api/v1/loans") ? loanPool
                : transferPool;
        log.info(() -> "APPGW L7 path " + path + " -> pool "
                + (pool == transferPool ? "transfer" : "loan"));
        return dataPlane.route(pool, srcIp, srcPort);  // TLS terminated here
    }
}
