package com.bank.azurelb.aks;

import java.util.List;
import java.util.stream.Collectors;
import java.util.logging.Logger;

// Represents an AKS Service type=LoadBalancer: Azure auto-provisions the LB
// and wires it to the healthy Pod endpoints.
public class AksLoadBalancerService {
    private static final Logger log = Logger.getLogger(AksLoadBalancerService.class.getName());
    private final List<String> podEndpoints;

    public AksLoadBalancerService(List<String> podEndpoints) {
        this.podEndpoints = podEndpoints;
        log.info(() -> "AKS Service type=LoadBalancer -> Azure LB auto-provisioned for "
                + podEndpoints.size() + " pods");
    }

    // Only READY pods (passing readiness probe) are in the backend pool.
    public List<String> healthyPods() {
        return podEndpoints.stream().filter(p -> !p.endsWith("#down")).collect(Collectors.toList());
    }
}
