package com.bank.azurelb.global;

import java.util.*;
import java.util.logging.Logger;

// Azure Front Door (global L7): route to NEAREST healthy region, failover.
public class FrontDoorGlobal {
    private static final Logger log = Logger.getLogger(FrontDoorGlobal.class.getName());
    private final Map<String, Boolean> regionHealthy = new LinkedHashMap<>();
    private final Map<String, Integer> latencyMs = new HashMap<>();

    public void addRegion(String region, boolean healthy, int latencyFromUserMs) {
        regionHealthy.put(region, healthy);
        latencyMs.put(region, latencyFromUserMs);
    }
    public void setHealthy(String region, boolean healthy) { regionHealthy.put(region, healthy); }

    // Pick the lowest-latency HEALTHY region (edge routing + failover).
    public String selectRegion() {
        return regionHealthy.entrySet().stream()
                .filter(Map.Entry::getValue)
                .min(Comparator.comparingInt(e -> latencyMs.get(e.getKey())))
                .map(e -> {
                    log.info(() -> "FRONT DOOR route to nearest healthy region: " + e.getKey()
                            + " (" + latencyMs.get(e.getKey()) + "ms)");
                    return e.getKey();
                })
                .orElseThrow(() -> new IllegalStateException("no healthy region"));
    }
}
