package com.bank.azurelb;

import com.bank.azurelb.aks.AksLoadBalancerService;
import com.bank.azurelb.global.FrontDoorGlobal;
import com.bank.azurelb.regional.ApplicationGatewayL7;
import java.util.List;
import java.util.logging.*;

public class AzureLbDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(AzureLbDemo.class.getName());

        // GLOBAL: Front Door knows two regions and their latency from the user.
        FrontDoorGlobal frontDoor = new FrontDoorGlobal();
        frontDoor.addRegion("centralindia", true, 20);
        frontDoor.addRegion("southeastasia", true, 90);
        String region = frontDoor.selectRegion();  // nearest = centralindia

        // AKS in the chosen region: auto-provisioned LB wired to healthy pods.
        AksLoadBalancerService aks = new AksLoadBalancerService(
                List.of("10.1.0.11", "10.1.0.12", "10.1.0.13#down"));
        List<String> transferPods = aks.healthyPods();                 // down pod excluded
        List<String> loanPods = List.of("10.1.1.21", "10.1.1.22");

        // REGIONAL L7: Application Gateway routes by path, runs WAF.
        ApplicationGatewayL7 appGw = new ApplicationGatewayL7();
        String a = appGw.route("/api/v1/transfers", "{\"amount\":50000}", "203.0.5.7", 51234,
                transferPods, loanPods);
        log.info("transfer request served by pod: " + a);
        String b = appGw.route("/api/v1/loans", "{\"principal\":200000}", "203.0.5.8", 51250,
                transferPods, loanPods);
        log.info("loan request served by pod: " + b);

        // WAF blocks a SQL-injection attempt before it reaches any pod.
        String c = appGw.route("/api/v1/transfers", "name=' OR '1'='1", "203.0.9.9", 51260,
                transferPods, loanPods);
        log.info("malicious request result: " + c);

        // Regional outage: Front Door fails over to the other region.
        log.severe("centralindia region is now UNHEALTHY");
        frontDoor.setHealthy("centralindia", false);
        String failover = frontDoor.selectRegion();  // now southeastasia
        log.info("after failover, Front Door routes to: " + failover);
    }
}

